create or replace function public.create_ai_incident_with_audit_atomic(
  p_incident_id uuid,
  p_organization_id uuid,
  p_actor_user_id uuid,
  p_ai_system_id uuid,
  p_title text,
  p_summary text,
  p_category text,
  p_severity text,
  p_detected_at timestamptz,
  p_report_status text,
  p_authority text,
  p_internal_owner text,
  p_deadline_plan jsonb,
  p_next_actions jsonb,
  p_audit_id uuid,
  p_audit_metadata jsonb,
  p_audit_created_at timestamptz,
  p_previous_hash text,
  p_event_hash text,
  p_hash_signature text default null
)
returns table(outcome text, incident jsonb)
language plpgsql
security definer
set search_path = 'pg_catalog', 'public'
as $$
declare
  v_previous_hash text;
  v_incident public.ai_incidents%rowtype;
begin
  if p_incident_id is null or p_organization_id is null or p_actor_user_id is null or p_audit_id is null then
    return query select 'invalid_input'::text, null::jsonb;
    return;
  end if;

  if length(trim(coalesce(p_title, ''))) = 0
    or length(trim(coalesce(p_summary, ''))) = 0
    or p_event_hash !~ '^[0-9a-f]{64}$'
    or (p_previous_hash is not null and p_previous_hash !~ '^[0-9a-f]{64}$')
    or (p_hash_signature is not null and p_hash_signature !~ '^[0-9a-f]{64}$') then
    return query select 'invalid_input'::text, null::jsonb;
    return;
  end if;

  if p_ai_system_id is not null and not exists (
    select 1 from public.ai_systems s
    where s.id = p_ai_system_id and s.organization_id = p_organization_id
  ) then
    return query select 'invalid_ai_system'::text, null::jsonb;
    return;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_organization_id::text));

  select ae.event_hash into v_previous_hash
  from public.audit_events ae
  where ae.organization_id = p_organization_id and ae.event_hash is not null
  order by ae.created_at desc, ae.id desc
  limit 1;

  if coalesce(v_previous_hash, '') <> coalesce(p_previous_hash, '') then
    raise exception 'audit chain previous hash mismatch' using errcode = '40001';
  end if;

  insert into public.ai_incidents (
    id, organization_id, ai_system_id, title, summary, category, severity,
    detected_at, report_status, authority, internal_owner, deadline_plan,
    next_actions, created_by
  ) values (
    p_incident_id, p_organization_id, p_ai_system_id, p_title, p_summary,
    p_category, p_severity, p_detected_at, p_report_status, p_authority,
    p_internal_owner, coalesce(p_deadline_plan, '[]'::jsonb),
    coalesce(p_next_actions, '[]'::jsonb), p_actor_user_id
  ) returning * into v_incident;

  insert into public.audit_events (
    id, organization_id, actor_user_id, action, entity_type, entity_id,
    metadata, created_at, previous_hash, event_hash, hash_algorithm, hash_signature
  ) values (
    p_audit_id, p_organization_id, p_actor_user_id, 'ai_incident_created',
    'ai_incident', p_incident_id::text, coalesce(p_audit_metadata, '{}'::jsonb),
    p_audit_created_at, v_previous_hash, p_event_hash, 'sha256', p_hash_signature
  );

  return query select 'created'::text, to_jsonb(v_incident);
end;
$$;

revoke all on function public.create_ai_incident_with_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, text, timestamptz, text, text, text, jsonb, jsonb, uuid, jsonb, timestamptz, text, text, text) from public;
revoke all on function public.create_ai_incident_with_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, text, timestamptz, text, text, text, jsonb, jsonb, uuid, jsonb, timestamptz, text, text, text) from anon;
revoke all on function public.create_ai_incident_with_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, text, timestamptz, text, text, text, jsonb, jsonb, uuid, jsonb, timestamptz, text, text, text) from authenticated;
grant execute on function public.create_ai_incident_with_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, text, timestamptz, text, text, text, jsonb, jsonb, uuid, jsonb, timestamptz, text, text, text) to service_role;

comment on function public.create_ai_incident_with_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, text, timestamptz, text, text, text, jsonb, jsonb, uuid, jsonb, timestamptz, text, text, text)
  is 'Creates one AI incident and its chained audit event atomically with organization-scoped serialization.';

begin;

do $hotfix$
declare
  fn_oid oid := to_regprocedure(
    'public.create_organization_invitation_with_seat_atomic_reconciled(uuid,text,text,text,text,uuid,timestamptz)'
  );
  fn_def text;
  patched_def text;
  old_fragment constant text := 'on conflict (organization_id) do nothing;';
  new_fragment constant text := 'on conflict on constraint organization_usage_pkey do nothing;';
begin
  if fn_oid is null then raise exception 'enterprise invitation reconciled function is missing'; end if;
  select pg_get_functiondef(fn_oid) into fn_def;
  if position(old_fragment in lower(fn_def)) = 0 then
    if position(new_fragment in lower(fn_def)) > 0 then return; end if;
    raise exception 'expected ambiguous ON CONFLICT fragment was not found';
  end if;
  patched_def := replace(fn_def, old_fragment, new_fragment);
  if patched_def = fn_def then raise exception 'enterprise invitation 42702 hotfix produced no change'; end if;
  execute patched_def;
end
$hotfix$;

do $verify$
declare
  fn_oid oid := to_regprocedure(
    'public.create_organization_invitation_with_seat_atomic_reconciled(uuid,text,text,text,text,uuid,timestamptz)'
  );
  fn_def text;
begin
  if fn_oid is null then raise exception 'enterprise invitation reconciled function missing after hotfix'; end if;
  select lower(pg_get_functiondef(fn_oid)) into fn_def;
  if position('on conflict (organization_id) do nothing;' in fn_def) > 0 then raise exception 'ambiguous invitation ON CONFLICT remains after hotfix'; end if;
  if position('on conflict on constraint organization_usage_pkey do nothing;' in fn_def) = 0 then raise exception 'constraint-qualified invitation ON CONFLICT is missing'; end if;
  if not exists (
    select 1 from pg_proc p cross join lateral unnest(coalesce(p.proconfig, array[]::text[])) setting
    where p.oid = fn_oid and p.prosecdef and setting = 'search_path=pg_catalog, public'
  ) then raise exception 'enterprise invitation reconciled function security boundary changed'; end if;
  if has_function_privilege('anon', fn_oid, 'EXECUTE')
     or has_function_privilege('authenticated', fn_oid, 'EXECUTE')
     or has_function_privilege('service_role', fn_oid, 'EXECUTE') then
    raise exception 'reconciled implementation unexpectedly became externally executable';
  end if;
end
$verify$;

notify pgrst, 'reload schema';
commit;

begin;

do $hotfix$
declare
  target regprocedure;
  target_name text;
  fn_def text;
  patched_def text;
  old_fragment constant text := 'on conflict (organization_id, user_id) do update set';
  new_fragment constant text := 'on conflict on constraint organization_members_organization_id_user_id_key do update set';
begin
  foreach target_name in array array[
    'public.accept_organization_invitation_atomic(text,uuid,text)',
    'public.accept_billing_organization_invitation_atomic(text,uuid,text)'
  ]
  loop
    target := to_regprocedure(target_name);
    if target is null then
      raise exception 'required invitation acceptance function is missing: %', target_name;
    end if;
    select pg_get_functiondef(target) into fn_def;
    if position(old_fragment in lower(fn_def)) = 0 then
      if position(new_fragment in lower(fn_def)) > 0 then
        continue;
      end if;
      raise exception 'expected membership conflict fragment was not found in %', target_name;
    end if;
    patched_def := replace(fn_def, old_fragment, new_fragment);
    if patched_def = fn_def then
      raise exception 'membership conflict hotfix produced no change for %', target_name;
    end if;
    execute patched_def;
  end loop;
end
$hotfix$;

do $verify$
declare
  target regprocedure;
  target_name text;
  fn_def text;
begin
  foreach target_name in array array[
    'public.accept_organization_invitation_atomic(text,uuid,text)',
    'public.accept_billing_organization_invitation_atomic(text,uuid,text)'
  ]
  loop
    target := to_regprocedure(target_name);
    if target is null then
      raise exception 'required invitation acceptance function missing after hotfix: %', target_name;
    end if;
    select lower(pg_get_functiondef(target)) into fn_def;
    if position('on conflict (organization_id, user_id) do update set' in fn_def) > 0 then
      raise exception 'ambiguous membership conflict target remains in %', target_name;
    end if;
    if position('on conflict on constraint organization_members_organization_id_user_id_key do update set' in fn_def) = 0 then
      raise exception 'constraint-qualified membership conflict target missing in %', target_name;
    end if;
    if not exists (
      select 1
      from pg_proc p
      cross join lateral unnest(coalesce(p.proconfig, array[]::text[])) setting
      where p.oid = target
        and p.prosecdef
        and setting = 'search_path=pg_catalog, public'
    ) then
      raise exception 'invitation acceptance security boundary changed for %', target_name;
    end if;
  end loop;
end
$verify$;

notify pgrst, 'reload schema';
commit;

