begin;

revoke all on function public.sync_legacy_risk_score() from public;
revoke all on function public.sync_legacy_risk_score() from anon;
revoke all on function public.sync_legacy_risk_score() from authenticated;
grant execute on function public.sync_legacy_risk_score() to service_role;

do $verify$
declare
  fn_oid oid := to_regprocedure('public.sync_legacy_risk_score()');
begin
  if fn_oid is null then
    raise exception 'public.sync_legacy_risk_score() is missing';
  end if;

  if has_function_privilege('anon', fn_oid, 'EXECUTE')
     or has_function_privilege('authenticated', fn_oid, 'EXECUTE')
     or not has_function_privilege('service_role', fn_oid, 'EXECUTE') then
    raise exception 'sync_legacy_risk_score ACL is not hardened as expected';
  end if;

  if not exists (
    select 1
    from pg_trigger t
    join pg_class c on c.oid=t.tgrelid
    join pg_namespace n on n.oid=c.relnamespace
    where not t.tgisinternal
      and t.tgfoid=fn_oid
      and n.nspname='public'
      and c.relname='risks'
      and t.tgname='sync_legacy_risk_score'
  ) then
    raise exception 'sync_legacy_risk_score trigger binding is missing';
  end if;
end
$verify$;

commit;
